retrieval.cypher:
MATCH (a:PlantItem {tag: 'P-401'}), (b:PlantItem {tag: 'P-504'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'CHV-4001' AND y.tag <> 'CHV-4001')+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

